## Code Example
```javascript
// insert/update logic
function apply(x, D, freq, total, op){
  const r = x % D;
  const idx = (D - r) % D;
  if(op==='insert'){ total += freq[idx]; freq[r]++; }
  else { freq[r]--; total -= freq[idx]; }
  return total;
}
```

